/****************************************************************************
 * GT911 板级回调: IRQ 附加
 ****************************************************************************/

static xcpt_t g_gt911_isr = NULL;
static FAR void *g_gt911_arg = NULL;

static int gt911_irq_attach(const struct gt9xx_board_s *state,
                            xcpt_t isr, FAR void *arg)
{
  uint32_t group = GPIO_GROUP(GT911_INT_PIN);
  uint32_t pin = GPIO_PIN(GT911_INT_PIN);
  uint32_t val;

  (void)state;

  /* 保存中断处理函数 */

  g_gt911_isr = isr;
  g_gt911_arg = arg;

  /* 配置 PA2 为 GPIO 通用功能 (PIN_FUN=1) */

  val = getreg32(D13X_GPIO_PIN_CFG(group, pin));
  val &= ~(PIN_CFG_FUN_MASK << PIN_CFG_FUN_SHIFT);
  val |= (GPIO_FUN_GEN << PIN_CFG_FUN_SHIFT);
  putreg32(val, D13X_GPIO_PIN_CFG(group, pin));

  /* 配置 PA2 为输入 */

  gpio_set_input(GT911_INT_PIN);

  /* 配置中断模式: 下降沿触发 (GT911 中断低电平有效) */

  val = getreg32(D13X_GPIO_PIN_CFG(group, pin));
  val &= ~(0x7 << PIN_CFG_IRQ_MODE_SHIFT);
  val |= (GPIO_IRQ_FALLING << PIN_CFG_IRQ_MODE_SHIFT);
  putreg32(val, D13X_GPIO_PIN_CFG(group, pin));

  /* 注册 GPIO 中断处理函数 */

  irq_attach(D13X_IRQ_GPIO, isr, arg);

  return OK;
}

/****************************************************************************
 * GT911 板级回调: IRQ 使能/禁用
 ****************************************************************************/

static void gt911_irq_enable(const struct gt9xx_board_s *state, bool enable)
{
  uint32_t group = GPIO_GROUP(GT911_INT_PIN);
  uint32_t pin = GPIO_PIN(GT911_INT_PIN);
  uint32_t val;

  (void)state;

  if (enable)
    {
      /* 清除中断状态 */

      putreg32((1 << pin), D13X_GPIO_IRQ_STAT(group));

      /* 使能 PA2 中断 */

      val = getreg32(D13X_GPIO_TRQ_EN(group));
      val |= (1 << pin);
      putreg32(val, D13X_GPIO_TRQ_EN(group));

      /* 使能 GPIO IRQ */

      up_enable_irq(D13X_IRQ_GPIO);
    }
  else
    {
      /* 禁用 PA2 中断 */

      val = getreg32(D13X_GPIO_TRQ_EN(group));
      val &= ~(1 << pin);
      putreg32(val, D13X_GPIO_TRQ_EN(group));
    }
}

