static int gt911_write_config(struct i2c_master_s *i2c)
{
  /* GT911 配置寄存器: 0x8047-0x80FE (184字节), 0x80FF (校验和), 0x8100 (版本/更新) */

  #define GT911_CONFIG_SIZE    184   /* 0x8047-0x80FE */
  #define GT911_CHECKSUM_REG   0x80FF
  #define GT911_UPDATE_REG     0x8100

  uint8_t buf[2 + GT911_CONFIG_SIZE + 2];  /* 寄存器地址 + 配置 + 校验和 + 更新标志 */
  uint8_t checksum = 0;
  int i;
