  /* 构建写缓冲区: 寄存器地址(0x8047) + 配置数据 + 校验和 + 更新标志 */

  buf[0] = 0x80;  /* 配置寄存器地址高字节 */
  buf[1] = 0x47;  /* 配置寄存器地址低字节 */

  /* 复制前 184 字节配置数据 */

  memcpy(&buf[2], gt911_config_table, GT911_CONFIG_SIZE);

  /* 计算校验和: 配置数据字节求和, 取反加1 */

  for (i = 0; i < GT911_CONFIG_SIZE; i++)
    {
      checksum += gt911_config_table[i];
    }

  checksum = (~checksum) + 1;
  buf[2 + GT911_CONFIG_SIZE] = checksum;      /* 0x80FF: 校验和 */
  buf[2 + GT911_CONFIG_SIZE + 1] = 0x01;      /* 0x8100: 写入标志 */

